"""VERL AgentLoop that replays trajectories generated by a fixed teacher.

This module deliberately lives outside the Vision-OPD checkout.  VERL loads it
through ``agent_loop_config_path`` and otherwise keeps its normal multimodal
post-processing, fixed-teacher forward pass, loss computation, optimizer, and
checkpoint code unchanged.
"""

from __future__ import annotations

from time import perf_counter
from typing import Any, Iterable

import numpy as np

from verl.experimental.agent_loop.agent_loop import (
    AgentLoopBase,
    AgentLoopMetrics,
    AgentLoopOutput,
)


def normalize_response_ids(
    value: Iterable[int] | np.ndarray,
    *,
    max_length: int,
    vocab_size: int,
) -> list[int]:
    """Validate and truncate a cached teacher trajectory."""

    if isinstance(value, np.ndarray):
        value = value.tolist()
    if not isinstance(value, (list, tuple)):
        raise TypeError(f"teacher_response_ids must be a list/tuple/ndarray, got {type(value)!r}")

    token_ids = [int(token_id) for token_id in value]
    if not token_ids:
        raise ValueError("teacher_response_ids must contain at least one token")
    invalid = [token_id for token_id in token_ids if token_id < 0 or token_id >= vocab_size]
    if invalid:
        raise ValueError(f"teacher_response_ids contains invalid token ids: {invalid[:8]}")
    if max_length <= 0:
        raise ValueError(f"max_length must be positive, got {max_length}")
    return token_ids[:max_length]


class TeacherTrajectoryAgentLoop(AgentLoopBase):
    """Return a cached teacher response instead of sampling from the student."""

    async def run(self, sampling_params: dict[str, Any], **kwargs) -> AgentLoopOutput:
        del sampling_params  # The trajectory is fixed and was generated offline by the teacher.

        trajectory_id = kwargs.get("trajectory_id", "<unknown>")
        messages = list(kwargs["raw_prompt"])

        started = perf_counter()
        multi_modal_data = await self.process_vision_info(messages)
        images = multi_modal_data.get("images")
        videos = multi_modal_data.get("videos")
        prompt_ids = await self.apply_chat_template(
            messages,
            images=images,
            videos=videos,
        )

        vocab_size = len(self.tokenizer)
        response_ids = normalize_response_ids(
            kwargs["teacher_response_ids"],
            max_length=self._get_response_length(),
            vocab_size=vocab_size,
        )
        elapsed = perf_counter() - started

        return AgentLoopOutput(
            prompt_ids=prompt_ids,
            response_ids=response_ids,
            response_mask=[1] * len(response_ids),
            response_logprobs=None,
            multi_modal_data=multi_modal_data,
            num_turns=2,
            metrics=AgentLoopMetrics(generate_sequences=elapsed),
            extra_fields={
                "trajectory_source": "fixed_teacher",
                "trajectory_id": str(trajectory_id),
            },
        )
